const scene=document.createElement('div');scene.className='spatial-scene';scene.setAttribute('aria-hidden','true');scene.innerHTML='<div class="spatial-depth"><i></i><i></i><i></i><b></b></div>';document.body.prepend(scene);
const nav=document.createElement('nav');nav.className='spatial-nav';nav.setAttribute('aria-label','ReleaseRadar workspaces');for(const [href,label] of [['./','◉ Regression lab'],['./#stress-lab','⚡ Stress lab'],['copilot.html','✦ QA Copilot'],['api-lab.html','◈ API Lab'],['testing-workbench.html','◇ Testing Workbench']]){const a=document.createElement('a');a.href=href;a.textContent=label;if(location.pathname.endsWith(href))a.setAttribute('aria-current','page');nav.append(a);}document.querySelector('main')?.prepend(nav);
const control=document.getElementById('background-motion')||document.createElement('button');if(!control.id){control.id='spatial-motion';document.querySelector('.top-actions,.bar-actions,.bar')?.append(control);}control.classList.add('spatial-toggle');control.type='button';
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let on=true;try{on=localStorage.getItem('rr-spatial-motion')!=='off';}catch{}
function update(){const active=on&&!reduced.matches;document.documentElement.dataset.spatialMotion=active?'on':'off';control.textContent=active?'Pause atmosphere':'Motion off';control.setAttribute('aria-pressed',String(active));control.disabled=reduced.matches;}
control.onclick=()=>{on=!on;try{localStorage.setItem('rr-spatial-motion',on?'on':'off');}catch{}update();};reduced.addEventListener('change',update);update();
let queued=false,x=0,y=0;function paint(){queued=false;if(document.documentElement.dataset.spatialMotion!=='on')return;const d=scene.firstElementChild;d.style.setProperty('--sx',`${x*35}px`);d.style.setProperty('--sy',`${y*28-Math.min(scrollY,1500)*.025}px`);d.style.setProperty('--sr',`${x*2}deg`);}function schedule(){if(!queued){queued=true;requestAnimationFrame(paint);}}addEventListener('pointermove',e=>{if(e.pointerType!=='mouse')return;x=e.clientX/innerWidth-.5;y=e.clientY/innerHeight-.5;schedule();},{passive:true});addEventListener('scroll',schedule,{passive:true});document.addEventListener('visibilitychange',()=>{scene.style.visibility=document.hidden?'hidden':'';});
